package dev.odin.controls;
import android.app.*;import android.content.*;import android.database.ContentObserver;import android.os.*;import android.provider.Settings;
/** Finite wake restoration; stock setting changes relinquish ownership. No polling. */
public final class SegmentService extends Service {
 static volatile boolean active;
 final Handler handler=new Handler(Looper.getMainLooper());volatile int generation;
 final Runnable check=new Runnable(){public void run(){if(SegmentSession.writing){handler.postDelayed(this,100);return;}if(!SegmentSession.owned(SegmentService.this))new Thread(()->Root.releaseSegments(SegmentService.this),"RingStockRestore").start();}};
 final ContentObserver observer=new ContentObserver(handler){@Override public void onChange(boolean self){handler.removeCallbacks(check);handler.postDelayed(check,300);}};
 void restoreLater(int epoch,long delay){handler.postDelayed(()->new Thread(()->{if(epoch!=generation)return;try{Root.resumeSegments(SegmentService.this);android.util.Log.i("RavenSegments","Wake restore finished, delay="+delay);}catch(Exception e){android.util.Log.e("RavenSegments","Wake restoration failed",e);ControlNotifications.recovery(SegmentService.this,ControlNotifications.LED_ALERT,"Raven · LED recovery",e.getMessage()==null?"Ring colors could not be restored after wake.":e.getMessage());}},"RingWakeRestore").start(),delay);}
 final BroadcastReceiver wake=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){String action=i.getAction();android.util.Log.i("RavenSegments","Screen event "+action);if(Intent.ACTION_SCREEN_OFF.equals(action)){generation++;new Thread(()->{try{Root.sleepSegments(SegmentService.this);}catch(Exception e){android.util.Log.e("RavenSegments","Sleep blanking failed",e);}},"RingSleep").start();}else if(Intent.ACTION_SCREEN_ON.equals(action)){int epoch=++generation;restoreLater(epoch,300);restoreLater(epoch,1200);}else if(Intent.ACTION_USER_PRESENT.equals(action)){restoreLater(generation,300);}}};
 @Override public void onCreate(){super.onCreate();active=true;ControlNotifications.ensure(this);startForeground(6,ControlNotifications.status(this,ControlNotifications.LED,"Raven LED segments","Restoring your ring colors after standby").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).putExtra("openTab","LEDs"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build());for(String key:DeviceState.LED_KEYS)getContentResolver().registerContentObserver(Settings.System.getUriFor(key),false,observer);IntentFilter events=new IntentFilter(Intent.ACTION_SCREEN_ON);events.addAction(Intent.ACTION_SCREEN_OFF);events.addAction(Intent.ACTION_USER_PRESENT);registerReceiver(wake,events,Context.RECEIVER_NOT_EXPORTED);}
 @Override public int onStartCommand(Intent i,int flags,int id){if(!SegmentSession.owned(this)){new Thread(()->Root.releaseSegments(this),"RingColdHandoff").start();stopSelf();return START_NOT_STICKY;}
  new Thread(()->{try{Root.resumeSegments(this);}catch(Exception e){android.util.Log.e("RavenSegments","Cold restoration failed",e);ControlNotifications.recovery(this,ControlNotifications.LED_ALERT,"Raven · LED recovery",e.getMessage()==null?"Ring colors could not be restored.":e.getMessage());}},"RingColdRestore").start();return START_STICKY;}
 @Override public void onDestroy(){active=false;generation++;handler.removeCallbacksAndMessages(null);getContentResolver().unregisterContentObserver(observer);unregisterReceiver(wake);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
